// ~30 ordinary programs with the verdict Judge0 gives each run. Each run is { stdin, expectedOutput, status }.
// Statuses are runCpp statuses. Run the same file against Judge0 later to confirm both providers agree
// (the compare-comment on each case says which Judge0 rule it exercises).
const T = 2000; // timeLimitMs for every program unless stated

module.exports = [
  { name: 'square', timeLimitMs: T, source: '#include <iostream>\nint main(){long long a; std::cin>>a; std::cout<<a*a<<"\\n";}',
    runs: [{ stdin: '5', expectedOutput: '25\n', status: 'accepted' }, { stdin: '-3', expectedOutput: '9', status: 'accepted' }, { stdin: '4', expectedOutput: '17', status: 'wrong_answer' }] },
  { name: 'hello world', timeLimitMs: T, source: '#include <cstdio>\nint main(){puts("Hello, World!");}',
    runs: [{ stdin: '', expectedOutput: 'Hello, World!\n', status: 'accepted' }] },
  { name: 'sum of n numbers', timeLimitMs: T, source: '#include <iostream>\nint main(){int n; std::cin>>n; long long s=0; while(n--){long long x; std::cin>>x; s+=x;} std::cout<<s;}',
    runs: [{ stdin: '3\n1 2 3\n', expectedOutput: '6', status: 'accepted' }, { stdin: '0\n', expectedOutput: '0', status: 'accepted' }] },
  { name: 'trailing spaces on lines are ignored', timeLimitMs: T, source: '#include <cstdio>\nint main(){printf("a  \\nb\\t\\n");}',
    runs: [{ stdin: '', expectedOutput: 'a\nb\n', status: 'accepted' }] },
  { name: 'CRLF output matches LF expected', timeLimitMs: T, source: '#include <cstdio>\nint main(){printf("1\\r\\n2\\r\\n");}',
    runs: [{ stdin: '', expectedOutput: '1\n2\n', status: 'accepted' }] },
  { name: 'trailing blank lines are ignored', timeLimitMs: T, source: '#include <cstdio>\nint main(){printf("x\\n\\n\\n");}',
    runs: [{ stdin: '', expectedOutput: 'x', status: 'accepted' }] },
  { name: 'leading whitespace matters', timeLimitMs: T, source: '#include <cstdio>\nint main(){printf(" x\\n");}',
    runs: [{ stdin: '', expectedOutput: 'x', status: 'wrong_answer' }] },
  { name: 'case matters', timeLimitMs: T, source: '#include <cstdio>\nint main(){puts("Yes");}',
    runs: [{ stdin: '', expectedOutput: 'yes', status: 'wrong_answer' }] },
  { name: 'blank line in the middle matters', timeLimitMs: T, source: '#include <cstdio>\nint main(){puts("a\\n\\nb");}',
    runs: [{ stdin: '', expectedOutput: 'a\nb', status: 'wrong_answer' }] },
  { name: 'no expected output: accepted whatever it prints', timeLimitMs: T, source: '#include <cstdio>\nint main(){puts("anything");}',
    runs: [{ stdin: '', status: 'accepted' }, { stdin: '', expectedOutput: '', status: 'accepted' }] },
  { name: 'empty output vs expected text', timeLimitMs: T, source: 'int main(){}',
    runs: [{ stdin: '', expectedOutput: 'something', status: 'wrong_answer' }] },
  { name: 'fibonacci with stl', timeLimitMs: T, source: '#include <iostream>\n#include <vector>\nint main(){int n; std::cin>>n; std::vector<long long> f(n+2); f[1]=1; for(int i=2;i<=n;i++) f[i]=f[i-1]+f[i-2]; std::cout<<f[n]<<std::endl;}',
    runs: [{ stdin: '10', expectedOutput: '55', status: 'accepted' }, { stdin: '50', expectedOutput: '12586269025', status: 'accepted' }] },
  { name: 'sort strings', timeLimitMs: T, source: '#include <iostream>\n#include <algorithm>\n#include <string>\n#include <vector>\nint main(){std::vector<std::string> v; std::string s; while(std::cin>>s) v.push_back(s); std::sort(v.begin(),v.end()); for(auto&x:v) std::cout<<x<<"\\n";}',
    runs: [{ stdin: 'pear apple fig', expectedOutput: 'apple\nfig\npear', status: 'accepted' }] },
  { name: 'compile error: missing semicolon', timeLimitMs: T, source: '#include <cstdio>\nint main(){ puts("x") }',
    runs: [{ stdin: '', expectedOutput: 'x', status: 'compile_error' }, { stdin: '', expectedOutput: 'x', status: 'compile_error' }] },
  { name: 'compile error: undeclared variable', timeLimitMs: T, source: 'int main(){ return y; }',
    runs: [{ stdin: '', expectedOutput: '', status: 'compile_error' }] },
  { name: 'compile error: no main', timeLimitMs: T, source: 'int f(){return 1;}',
    runs: [{ stdin: '', expectedOutput: '1', status: 'compile_error' }] },
  { name: 'runtime error: non-zero exit code', timeLimitMs: T, source: '#include <cstdio>\nint main(){puts("partial"); return 3;}',
    runs: [{ stdin: '', expectedOutput: 'partial', status: 'runtime_error' }] },
  { name: 'runtime error: division by zero', timeLimitMs: T, source: '#include <iostream>\nint main(){int a,b; std::cin>>a>>b; std::cout<<a/b;}',
    runs: [{ stdin: '6 3', expectedOutput: '2', status: 'accepted' }, { stdin: '1 0', expectedOutput: '0', status: 'runtime_error' }] },
  { name: 'runtime error: out_of_range exception', timeLimitMs: T, source: '#include <vector>\nint main(){std::vector<int> v(2); return v.at(5);}',
    runs: [{ stdin: '', expectedOutput: '', status: 'runtime_error' }] },
  { name: 'too slow: busy loop', timeLimitMs: 1000, source: 'int main(){ volatile unsigned long long x=0; for(unsigned long long i=0;i<40000000000ULL;i++) x+=i; }',
    runs: [{ stdin: '', expectedOutput: '', status: 'time_limit' }] },
  { name: 'quick loop stays under the limit', timeLimitMs: 2000, source: '#include <cstdio>\nint main(){ volatile unsigned long long x=0; for(int i=0;i<100000000;i++) x+=i; printf("%llu\\n",(unsigned long long)x); }',
    runs: [{ stdin: '', expectedOutput: '4999999950000000', status: 'accepted' }] },
  { name: 'uses 64 MB and is fine at the 128 MB limit', timeLimitMs: T, memoryLimitKb: 128000, source: '#include <vector>\n#include <cstdio>\nint main(){ std::vector<char> v(64<<20, 1); long s=0; for(char c: v) s+=c; printf("%ld\\n", s); }',
    runs: [{ stdin: '', expectedOutput: '67108864', status: 'accepted' }] },
  { name: 'wants 600 MB with a 128 MB limit', timeLimitMs: T, memoryLimitKb: 128000, source: '#include <vector>\n#include <cstdio>\nint main(){ std::vector<char> v(600<<20, 1); printf("%d\\n", (int)v[100]); }',
    runs: [{ stdin: '', expectedOutput: '1', status: 'memory_limit' }] },
  { name: 'deep recursion (50k frames) works', timeLimitMs: T, source: '#include <cstdio>\nlong f(long n){ return n==0 ? 0 : 1+f(n-1); }\nint main(){ printf("%ld\\n", f(50000)); }',
    runs: [{ stdin: '', expectedOutput: '50000', status: 'accepted' }] },
  { name: 'reads a large input', timeLimitMs: T, source: '#include <iostream>\nint main(){ long long s=0,x; while(std::cin>>x) s+=x; std::cout<<s<<"\\n"; }',
    runs: [{ stdin: Array.from({ length: 100000 }, (_, i) => i).join(' '), expectedOutput: '4999950000', status: 'accepted' }] },
  { name: 'non-UTF-8 output vs text expected', timeLimitMs: T, source: '#include <cstdio>\nint main(){ fputs("\\xff\\xfe\\n", stdout); }',
    runs: [{ stdin: '', expectedOutput: 'x', status: 'wrong_answer' }] },
  { name: 'uninitialised-free arithmetic with doubles', timeLimitMs: T, source: '#include <cstdio>\nint main(){ printf("%.2f\\n", 10.0/4); }',
    runs: [{ stdin: '', expectedOutput: '2.50', status: 'accepted' }, { stdin: '', expectedOutput: '2.5', status: 'wrong_answer' }] },
  { name: 'abort() is a runtime error', timeLimitMs: T, source: '#include <cstdlib>\nint main(){ abort(); }',
    runs: [{ stdin: '', expectedOutput: '', status: 'runtime_error' }] },
  { name: 'assert failure is a runtime error', timeLimitMs: T, source: '#include <cassert>\nint main(){ assert(1 == 2); }',
    runs: [{ stdin: '', expectedOutput: '', status: 'runtime_error' }] }
];
